<?php $page_title='Billing';require_once __DIR__.'/../includes/header.php';$rows=$pdo->query("SELECT b.*,p.name patient FROM bills b JOIN patients p ON p.id=b.patient_id ORDER BY b.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Billing</h2><a href="add.php" class="btn btn-primary">+ Create Bill</a></div><div class="card p-3"><table class="table"><thead><tr><th>Invoice</th><th>Patient</th><th>Description</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td>#<?=$b['invoice_no']?></td><td><?=e($b['patient'])?></td><td><?=e($b['description'])?></td><td>$<?=number_format($b['amount'],2)?></td><td><?=$b['method']?></td><td><?=$b['status']?></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>